// TENANT-SCOPED DATA LAYER for vendor risk (vendors, vendor_assessments, vendor_events). Only this file runs SQL on them.
import { q, type Conn } from '../../db'; import type { Category, Criticality, DataAccess, VStatus, AnswerMap } from './rules';
const D = (col: string, as: string) => `DATE_FORMAT(${col},'%Y-%m-%d') ${as}`;
const COLS = `v.id, v.vendor_no vendorNo, v.name, v.service, v.category, v.criticality, v.data_access dataAccess, v.status, v.owner_user_id ownerUserId, ou.name ownerName, v.contact_user_id contactUserId, cu.name contactUserName, v.contact_name contactName, v.contact_email contactEmail,
  ${D('v.contract_start', 'contractStart')}, ${D('v.contract_end', 'contractEnd')}, ${D('v.review_date', 'reviewDate')}, v.created_by createdById, au.name createdBy, v.created_at createdAt, v.updated_at updatedAt, v.offboarded_at offboardedAt`;
const FROM = 'FROM vendors v LEFT JOIN users ou ON ou.id=v.owner_user_id LEFT JOIN users cu ON cu.id=v.contact_user_id JOIN users au ON au.id=v.created_by';
const LATEST = `(SELECT a.status FROM vendor_assessments a WHERE a.tenant_id=v.tenant_id AND a.vendor_id=v.id ORDER BY a.assessment_no DESC LIMIT 1) latestStatus,
  (SELECT a.score FROM vendor_assessments a WHERE a.tenant_id=v.tenant_id AND a.vendor_id=v.id AND a.status IN ('approved','rejected') ORDER BY a.assessment_no DESC LIMIT 1) latestScore,
  (SELECT a.status FROM vendor_assessments a WHERE a.tenant_id=v.tenant_id AND a.vendor_id=v.id AND a.status IN ('draft','submitted') LIMIT 1) openStatus,
  (SELECT COUNT(*) FROM vendor_assessments a WHERE a.tenant_id=v.tenant_id AND a.vendor_id=v.id AND a.status='approved') approvedCount`;
export type ListFilter = { status?: VStatus; ownerUserId?: string; contactUserId?: string; category?: Category };
export function listVendors(c: Conn, tenantId: string, f: ListFilter = {}) { const w = ['v.tenant_id=?']; const p: any[] = [tenantId]; if (f.status) { w.push('v.status=?'); p.push(f.status); } if (f.ownerUserId) { w.push('v.owner_user_id=?'); p.push(f.ownerUserId); } if (f.contactUserId) { w.push('v.contact_user_id=?'); p.push(f.contactUserId); } if (f.category) { w.push('v.category=?'); p.push(f.category); }
  return q(c, `SELECT ${COLS}, ${LATEST} ${FROM} WHERE ${w.join(' AND ')} ORDER BY FIELD(v.status,'onboarding','active','offboarding','offboarded'), v.name LIMIT 2001`, p); }
export async function getVendor(c: Conn, tenantId: string, id: string, lock = false) { if (lock && !(await q(c, 'SELECT id FROM vendors WHERE tenant_id=? AND id=? FOR UPDATE', [tenantId, id]))[0]) return null; return (await q(c, `SELECT ${COLS}, ${LATEST} ${FROM} WHERE v.tenant_id=? AND v.id=?`, [tenantId, id]))[0] ?? null; }
export const lockTenant = (c: Conn, tenantId: string) => q(c, 'SELECT id FROM organizations WHERE id=? FOR UPDATE', [tenantId]);
export const nextNo = async (c: Conn, tenantId: string) => Number((await q(c, 'SELECT COALESCE(MAX(vendor_no),0)+1 n FROM vendors WHERE tenant_id=?', [tenantId]))[0].n);
export type NewVendor = { id: string; no: number; name: string; service: string; category: Category; criticality: Criticality; dataAccess: DataAccess; ownerUserId?: string | null; contactUserId?: string | null; contactName?: string | null; contactEmail?: string | null; contractStart?: string | null; contractEnd?: string | null; createdBy: string };
export const insertVendor = (c: Conn, tenantId: string, v: NewVendor) => c.query('INSERT INTO vendors(tenant_id,id,vendor_no,name,service,category,criticality,data_access,owner_user_id,contact_user_id,contact_name,contact_email,contract_start,contract_end,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
  [tenantId, v.id, v.no, v.name, v.service, v.category, v.criticality, v.dataAccess, v.ownerUserId ?? null, v.contactUserId ?? null, v.contactName ?? null, v.contactEmail ?? null, v.contractStart ?? null, v.contractEnd ?? null, v.createdBy]);
const FIELD_COLS: Record<string, string> = { name: 'name', service: 'service', category: 'category', criticality: 'criticality', dataAccess: 'data_access', ownerUserId: 'owner_user_id', contactUserId: 'contact_user_id', contactName: 'contact_name', contactEmail: 'contact_email', contractStart: 'contract_start', contractEnd: 'contract_end', reviewDate: 'review_date' };
export async function updateFields(c: Conn, tenantId: string, id: string, patch: Record<string, unknown>) { const keys = Object.keys(patch).filter(k => k in FIELD_COLS); if (!keys.length) return; await c.query(`UPDATE vendors SET ${keys.map(k => `${FIELD_COLS[k]}=?`).join(',')} WHERE tenant_id=? AND id=?`, [...keys.map(k => patch[k] ?? null), tenantId, id]); }
export const setStatus = (c: Conn, tenantId: string, id: string, to: VStatus) => c.query(`UPDATE vendors SET status=?, offboarded_at=${to === 'offboarded' ? 'NOW(3)' : 'NULL'} WHERE tenant_id=? AND id=?`, [to, tenantId, id]);
export const addEvent = (c: Conn, tenantId: string, e: { id: string; vendorId: string; kind: 'created' | 'edited' | 'status' | 'assessment' | 'comment'; from?: string | null; to?: string | null; note?: string | null; actorId: string }) =>
  c.query('INSERT INTO vendor_events(tenant_id,id,vendor_id,kind,from_status,to_status,note,actor_id) VALUES (?,?,?,?,?,?,?,?)', [tenantId, e.id, e.vendorId, e.kind, e.from ?? null, e.to ?? null, e.note ?? null, e.actorId]);
export const listEvents = (c: Conn, tenantId: string, vendorId: string) => q(c, 'SELECT e.id, e.kind, e.from_status fromStatus, e.to_status toStatus, e.note, u.name actorName, e.created_at createdAt FROM vendor_events e JOIN users u ON u.id=e.actor_id WHERE e.tenant_id=? AND e.vendor_id=? ORDER BY e.created_at, e.id', [tenantId, vendorId]);
// ---- assessments
const ACOLS = `a.id, a.vendor_id vendorId, a.assessment_no assessmentNo, a.questionnaire_version version, a.status, a.answers, a.score, ${D('a.due_date', 'dueDate')}, a.requested_by requestedById, ru.name requestedBy, a.submitted_by submittedById, su.name submittedBy, a.submitted_at submittedAt, a.reviewed_by reviewedById, vu.name reviewedBy, a.reviewed_at reviewedAt, a.review_note reviewNote, a.created_at createdAt`;
const AFROM = 'FROM vendor_assessments a JOIN users ru ON ru.id=a.requested_by LEFT JOIN users su ON su.id=a.submitted_by LEFT JOIN users vu ON vu.id=a.reviewed_by';
const parse = (x: any) => x ? { ...x, answers: (typeof x.answers === 'string' ? JSON.parse(x.answers) : x.answers) as AnswerMap } : null;
export const listAssessments = async (c: Conn, tenantId: string, vendorId: string) => (await q(c, `SELECT ${ACOLS} ${AFROM} WHERE a.tenant_id=? AND a.vendor_id=? ORDER BY a.assessment_no DESC`, [tenantId, vendorId])).map(parse);
export async function getAssessment(c: Conn, tenantId: string, vendorId: string, id: string, lock = false) { if (lock && !(await q(c, 'SELECT id FROM vendor_assessments WHERE tenant_id=? AND vendor_id=? AND id=? FOR UPDATE', [tenantId, vendorId, id]))[0]) return null; return parse((await q(c, `SELECT ${ACOLS} ${AFROM} WHERE a.tenant_id=? AND a.vendor_id=? AND a.id=?`, [tenantId, vendorId, id]))[0]); }
export const hasOpenAssessment = async (c: Conn, tenantId: string, vendorId: string) => !!(await q(c, "SELECT 1 x FROM vendor_assessments WHERE tenant_id=? AND vendor_id=? AND status IN ('draft','submitted') LIMIT 1", [tenantId, vendorId]))[0];
export const nextAssessmentNo = async (c: Conn, tenantId: string, vendorId: string) => Number((await q(c, 'SELECT COALESCE(MAX(assessment_no),0)+1 n FROM vendor_assessments WHERE tenant_id=? AND vendor_id=?', [tenantId, vendorId]))[0].n);
export const insertAssessment = (c: Conn, tenantId: string, a: { id: string; vendorId: string; no: number; dueDate?: string | null; requestedBy: string }) => c.query("INSERT INTO vendor_assessments(tenant_id,id,vendor_id,assessment_no,answers,due_date,requested_by) VALUES (?,?,?,?,'{}',?,?)", [tenantId, a.id, a.vendorId, a.no, a.dueDate ?? null, a.requestedBy]);
export const saveAnswers = (c: Conn, tenantId: string, id: string, answers: AnswerMap) => c.query("UPDATE vendor_assessments SET answers=? WHERE tenant_id=? AND id=? AND status='draft'", [JSON.stringify(answers), tenantId, id]);
export const markSubmitted = (c: Conn, tenantId: string, id: string, score: number, by: string) => c.query("UPDATE vendor_assessments SET status='submitted', score=?, submitted_by=?, submitted_at=NOW(3) WHERE tenant_id=? AND id=? AND status='draft'", [score, by, tenantId, id]);
export const markReturned = (c: Conn, tenantId: string, id: string, note: string) => c.query("UPDATE vendor_assessments SET status='draft', score=NULL, submitted_by=NULL, submitted_at=NULL, review_note=? WHERE tenant_id=? AND id=? AND status='submitted'", [note, tenantId, id]);
export const markDecided = (c: Conn, tenantId: string, id: string, to: 'approved' | 'rejected', by: string, note: string | null) => c.query("UPDATE vendor_assessments SET status=?, reviewed_by=?, reviewed_at=NOW(3), review_note=? WHERE tenant_id=? AND id=? AND status='submitted'", [to, by, note, tenantId, id]);
export const latestApproved = async (c: Conn, tenantId: string, vendorId: string) => (await q(c, `SELECT ${D('reviewed_at', 'decidedOn')}, score FROM vendor_assessments WHERE tenant_id=? AND vendor_id=? AND status='approved' ORDER BY assessment_no DESC LIMIT 1`, [tenantId, vendorId]))[0] ?? null;
export const setReviewDate = (c: Conn, tenantId: string, id: string, date: string | null) => c.query('UPDATE vendors SET review_date=? WHERE tenant_id=? AND id=?', [date, tenantId, id]);
// ---- people
export const isOwnerCandidate = async (c: Conn, tenantId: string, userId: string) => !!(await q(c, "SELECT 1 x FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.tenant_id=? AND m.user_id=? AND m.role IN ('client_admin','client_staff') AND u.status='active'", [tenantId, userId]))[0];
export const isContactCandidate = async (c: Conn, tenantId: string, userId: string) => !!(await q(c, "SELECT 1 x FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.tenant_id=? AND m.user_id=? AND m.role='third_party_vendor' AND u.status='active'", [tenantId, userId]))[0];
export const openVendorsFor = (c: Conn, userId: string, tenantId: string | null) => q(c, `SELECT v.id, v.vendor_no n, v.name, o.name orgName FROM vendors v JOIN organizations o ON o.id=v.tenant_id WHERE (v.owner_user_id=? OR v.contact_user_id=?) AND v.status <> 'offboarded' ${tenantId ? 'AND v.tenant_id=?' : ''}`, tenantId ? [userId, userId, tenantId] : [userId, userId]);
export const vendorsAddedBy = (c: Conn, userId: string) => q(c, 'SELECT v.vendor_no n, v.name, v.status, v.created_at createdAt, o.name orgName FROM vendors v JOIN organizations o ON o.id=v.tenant_id WHERE v.created_by=? ORDER BY v.created_at', [userId]);
